(() => {
  const all = document.querySelectorAll('*');
  for (const el of all) {
    if (el.children.length === 0 && el.textContent.trim() === 'river-flash-8094') {
      const parent = el.parentElement;
      const tag = el.tagName.toLowerCase();
      const id = el.id ? '#' + el.id : '';
      const cls = el.className ? '.' + String(el.className).trim().split(/\s+/).join('.') : '';
      return { tag, id, cls, parentTag: parent.tagName.toLowerCase(), parentCls: parent.className, text: el.textContent };
    }
  }
  return null;
})()

(() => {
  const codes = document.querySelectorAll('code');
  const result = [];
  for (const el of codes) {
    const section = el.closest('section');
    const heading = section ? section.querySelector('h2') : null;
    result.push({
      text: el.textContent,
      sectionClass: section ? section.className : null,
      headingText: heading ? heading.textContent : null
    });
  }
  return result;
})()

(() => {
  const sections = document.querySelectorAll('section');
  const result = [];
  for (const s of sections) {
    const h2 = s.querySelector('h2');
    result.push({
      html: s.outerHTML.substring(0, 400),
      heading: h2 ? h2.textContent : null
    });
  }
  return result;
})()

